// Minimal MCP stdio client: spawns the same command OpenClaw registered and runs a list of calls.
import { spawn } from 'node:child_process';
const calls = JSON.parse(process.argv[2] || '[]');
const bin = process.env.HOME + '/.bun/bin/gbrain';
const p = spawn(bin, ['serve', '--surface', 'starter', '--advertise', 'verbs'], {
  env: { ...process.env, GBRAIN_HOME: process.env.HOME }, stdio: ['pipe', 'pipe', 'pipe'],
});
let buf = ''; const pending = new Map(); let id = 0;
p.stdout.on('data', d => {
  buf += d; let i;
  while ((i = buf.indexOf('\n')) >= 0) {
    const line = buf.slice(0, i); buf = buf.slice(i + 1);
    if (!line.trim()) continue;
    try { const m = JSON.parse(line); if (m.id != null && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } } catch {}
  }
});
let err = ''; p.stderr.on('data', d => { err += d; });
const rpc = (method, params) => new Promise(r => { const i = ++id; pending.set(i, r); p.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: i, method, params }) + '\n'); });
const t = setTimeout(() => { console.error('TIMEOUT\n' + err.slice(-2000)); process.exit(2); }, 120000);
const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'install-check', version: '1' } });
console.log('server:', JSON.stringify(init.result?.serverInfo));
p.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
for (const c of calls) {
  if (c === 'list') { const r = await rpc('tools/list', {}); console.log('tools:', r.result.tools.map(x => x.name).join(', ')); if (process.env.SCHEMA) for (const x of r.result.tools) if (process.env.SCHEMA.split(',').includes(x.name)) console.log(x.name, JSON.stringify(x.inputSchema)); continue; }
  const r = await rpc('tools/call', { name: c.name, arguments: c.args });
  console.log(`== ${c.name}:`, JSON.stringify(r.result ?? r.error).slice(0, 2500));
}
clearTimeout(t); p.stdin.end(); p.kill(); process.exit(0);

